def upload_all(uploader, records):
    def send_all(items):
        failed = set()
        for i in range(0, len(items), uploader.max_batch):
            failed.update(uploader.send(items[i:i + uploader.max_batch]))
        return failed
    failed = send_all(records)
    if not failed:
        return []
    retry = [r for r in records if r["id"] in failed]
    return sorted(send_all(retry))
